    return {'key': key, 'kind': kind, 'name': name, 'one': one, 'stance': stance, 'domains': list(domains), 'slang': list(slang), 'tree': tree, 'mkey': mkey,
            'gate': dict(zip(('货源', '技能', '资质', '交付'), gate))}

